javascript:
frappe.query_reports["Stock Turnover"] = {
    filters: [
        {
            fieldname: "company",
            label: __("Company"),
            fieldtype: "Link",
            options: "Company",
            reqd: 1,
            default: frappe.defaults.get_user_default("Company")
        },

        {
            fieldname: "from_date",
            label: __("From Date"),
            fieldtype: "Date",
            reqd: 1,
            default: erpnext.utils.get_fiscal_year(frappe.datetime.get_today(), true)[1]
        },

        {
            fieldname: "to_date",
            label: __("To Date"),
            fieldtype: "Date",
            reqd: 1,
            default: frappe.datetime.get_today()
        },

        {
            fieldname: "warehouse",
            label: __("Warehouse"),
            fieldtype: "Link",
            options: "Warehouse",

            get_query: function () {
                return {
                    filters: {
                        company: frappe.query_report.get_filter_value("company")
                    }
                };
            }
        },

        {
            fieldname: "item_group",
            label: __("Item Group"),
            fieldtype: "Link",
            options: "Item Group"
        },

        {
            fieldname: "item_code",
            label: __("Item"),
            fieldtype: "Link",
            options: "Item"
        },

        {
            fieldname: "high_turnover",
            label: __("High Turnover"),
            fieldtype: "Float",
            default: 6,
            description: __("Annualized turnover ratio considered High.")
        },

        {
            fieldname: "normal_turnover",
            label: __("Normal Turnover"),
            fieldtype: "Float",
            default: 3,
            description: __("Annualized turnover ratio considered Normal.")
        },

        {
            fieldname: "low_turnover",
            label: __("Low Turnover"),
            fieldtype: "Float",
            default: 1,
            description: __("Annualized turnover ratio considered Low.")
        }
    ]
};
